from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=root.parent/'d3-sommni-site/src/app/App.tsx'
s=p.read_text()
start='// SOMMNI INITIATIVE SHARED UI START'
if start in s:s=s[:s.index(start)]
else:
 s=s.replace('</div></div><section id="winebrary"','</div></div><SommniInitiativeBanner client={client} signin={signin}/><section id="winebrary"',1)
 s=s.replace('<button className="sn-btn" onClick={()=>setSelected(null)}>Close notes</button></div></section>','<button className="sn-btn" onClick={()=>setSelected(null)}>Close notes</button></div><SommniPublicTastings client={client} wine={{ref:selected.id,name:selected.wine.name.split(\' – \')[0],producer:selected.wine.name.split(\' – \').slice(1).join(\' – \')}} signin={signin}/></section>',1)
 s=s.replace('{wine.notes&&<details><summary>My private notes</summary>', '<SommniLibraryTastings client={client} wine={wine} signin={signin}/>{wine.notes&&<details><summary>My private notes</summary>',1)
 s=s.replace('const next=data as SommniCommunityState;setState(next);','const initiative=await client.rpc(\'sommni_initiative_state\');if(initiative.error)throw initiative.error;if(identity.current!==captured)return;const next={...data,score:initiative.data.points,leaderboard:initiative.data.leaderboard.map((r:any)=>({handle:r.handle,wines:r.points}))} as SommniCommunityState;setState(next);',1)
 s=s.replace("setState(data as SommniCommunityState);setMessage('Contributor profile saved.","await refresh();setMessage('Contributor profile saved.",1)
 s=s.replace('<b>1</b> verified wine + vintage = 1 point','<b>10</b> points · verified new wine + vintage').replace('Repeat submissions = no extra points','1 · rating / +2 · tasting comment (40+ characters)').replace('validated contributions<br/>','contribution points<br/>').replace('validated contribution count on the leaderboard','contribution points on the leaderboard').replace('<th>Validated</th>','<th>Points</th>').replace('Public contributors appear here after review.','Opt in and share a public tasting to join the leaderboard.').replace('The first discoveries are waiting to be validated.','Be among the first to light up the map.').replace('Saving to your personal Winebrary does not earn contribution points.','Public ratings earn 1 point, with 2 more for a tasting comment of 40+ characters. Edits and repeats earn no extra points.')
 s=s.replace('<h2>Contributions and public wine facts</h2>','<h2>Public ratings and tasting comments</h2><p>Publishing a community tasting shares your chosen contributor name, wine rating, optional vintage, comment and posting date with other visitors. This requires an account and explicit confirmation. It never copies your private Winebrary notes automatically. You can edit or remove your published tasting, and report another contribution for review. Contribution points reward active ratings, detailed tasting comments and verified wine discoveries. Leaderboard visibility is optional.</p><h2>Contributions and public wine facts</h2>',1)
shared=((root/'src/community/atlas-activity-ui.ts').read_text()+'\n'+(root/'src/community/initiative-ui.ts').read_text().replace("import { mountAtlasActivity } from './atlas-activity-ui';\n",'')).replace('export ','')
wrapper='''
function SommniInitiativeBanner({client,signin}:{client:SupabaseClient;signin:()=>void}){const ref=useRef<HTMLDivElement>(null);const signinRef=useRef(signin);signinRef.current=signin;useEffect(()=>{if(!ref.current)return;return mountInitiativeBanner(ref.current,client,()=>signinRef.current(),()=>{const panel=document.querySelector<HTMLDetailsElement>('.sn-submit-panel');if(panel){panel.open=true;panel.scrollIntoView({block:'start',behavior:'smooth'});panel.querySelector<HTMLInputElement>('input')?.focus({preventScroll:true})}})},[client]);return <div ref={ref}/>}
function SommniPublicTastings({client,wine,signin}:{client:SupabaseClient;wine:ReviewWine;signin:()=>void}){const ref=useRef<HTMLDivElement>(null);const signinRef=useRef(signin);signinRef.current=signin;useEffect(()=>{if(!ref.current)return;return mountWineCommunity(ref.current,client,wine,()=>signinRef.current())},[client,wine.ref,wine.name,wine.producer,wine.vintage]);return <div ref={ref}/>}
function SommniLibraryTastings({client,wine,signin}:{client:SupabaseClient;wine:any;signin:()=>void}){const [open,setOpen]=useState(false);return <div><button className="sn-btn" onClick={()=>setOpen(!open)}>{open?'Close community tastings':'Rate & discuss this wine'}</button>{open&&<SommniPublicTastings client={client} wine={{ref:wine.wine_id||'',name:wine.wine_name,producer:wine.producer||'',vintage:wine.vintage?String(wine.vintage):wine.metadata?.vintage_state==='non_vintage'?'NV':'unknown'}} signin={signin}/>}</div>}
'''
s+='\n'+start+'\n'+shared+'\n'+wrapper
p.write_text(s)
